import { Modal, Notice } from "obsidian";
import { StrictMode, useState } from "react";
import { createRoot, type Root } from "react-dom/client";
import { ZodError } from "zod";
import type DiscourseGraphPlugin from "~/index";
import {
  applySchemaImportSelection,
  pickAndPreviewSchemaImport,
  type ImportPreviewStats,
  type LoadedSchemaFile,
  type SpecImportApplyResult,
  type SpecImportPreview,
} from "~/utils/specImport";
import type { SchemaConflict } from "~/utils/schemaFieldDiff";
import { NativeFileDialogCancelledError } from "~/utils/nativeJsonFileDialogs";
import {
  useSchemaSelection,
  type SchemaSelectionState,
} from "~/components/useSchemaSelection";
import { SchemaSelectionPanel } from "~/components/SchemaSelectionPanel";
import { ImportSchemaPreviewSummary } from "~/components/ImportSchemaPreviewSummary";
import { SchemaConflictResolutionStep } from "~/components/SchemaConflictResolutionStep";
import { useSchemaMergePlan } from "~/components/useSchemaMergePlan";

type ImportSpecsModalProps = {
  plugin: DiscourseGraphPlugin;
  onClose: () => void;
};

/** A step of its own: per-field choices folded into the selection list would bury the decision that changes existing data. */
type ImportStep = "select" | "choose";

export const openImportSpecsModal = (plugin: DiscourseGraphPlugin): void => {
  new ImportSpecsModal(plugin).open();
};

/** Overlaps are computed for the whole file, so drop the ones not being imported. */
const filterConflictsToSelection = ({
  conflicts,
  selection,
}: {
  conflicts: SchemaConflict[];
  selection: SchemaSelectionState;
}): SchemaConflict[] => {
  return conflicts.filter((conflict) => {
    if (conflict.category === "nodeType") {
      return selection.selectedNodeTypeIds.has(conflict.schemaId);
    }
    if (conflict.category === "relationType") {
      return selection.selectedRelationTypeIds.has(conflict.schemaId);
    }
    return selection.selectedTemplateNames.has(conflict.schemaId);
  });
};

const buildExistingItemNotes = ({
  existingSchemaIds,
  conflicts,
  category,
}: {
  existingSchemaIds: ReadonlySet<string>;
  conflicts: SchemaConflict[];
  category: SchemaConflict["category"];
}): Map<string, string> => {
  const changeCountBySchemaId = new Map(
    conflicts
      .filter((conflict) => conflict.category === category)
      .map((conflict) => [conflict.schemaId, conflict.changes.length]),
  );
  return new Map(
    [...existingSchemaIds].map((schemaId) => {
      const changeCount = changeCountBySchemaId.get(schemaId);
      return [
        schemaId,
        changeCount
          ? `in vault, ${changeCount} field(s) differ`
          : "in vault, identical",
      ];
    }),
  );
};

const buildImportCompleteMessage = ({
  created,
  merged,
}: SpecImportApplyResult): string => {
  const createdMessage = `Import complete: ${created.nodeTypes} node type(s), ${created.relationTypes} relation type(s), ${created.discourseRelations} relation triple(s), and ${created.templates} template(s) created.`;
  const mergedTotal =
    merged.nodeTypes + merged.relationTypes + merged.templates;
  if (mergedTotal === 0) return createdMessage;
  return `${createdMessage} Updated ${merged.nodeTypes} node type(s) and ${merged.relationTypes} relation type(s), and added ${merged.templates} template copy(ies).`;
};

const ImportPreviewSelection = ({
  plugin,
  loadedSchemaFile,
  previewStats,
  conflicts,
  isApplyingImport,
  setIsApplyingImport,
  onResetPreview,
  onClose,
}: {
  plugin: DiscourseGraphPlugin;
  loadedSchemaFile: LoadedSchemaFile;
  previewStats: ImportPreviewStats;
  conflicts: SchemaConflict[];
  isApplyingImport: boolean;
  setIsApplyingImport: (value: boolean) => void;
  onResetPreview: () => void;
  onClose: () => void;
}) => {
  const [step, setStep] = useState<ImportStep>("select");
  const schemaFile = loadedSchemaFile.schemaFile;
  const source = {
    nodeTypes: schemaFile.nodeTypes,
    relationTypes: schemaFile.relationTypes,
    relationTriples: schemaFile.discourseRelations,
    templateNames: schemaFile.templates.map((template) => template.name),
  };

  const selection = useSchemaSelection({
    source,
    resetKey: loadedSchemaFile.sourcePath,
  });

  const selectedConflicts = filterConflictsToSelection({
    conflicts,
    selection,
  });

  const mergePlan = useSchemaMergePlan({
    resetKey: `${loadedSchemaFile.sourcePath}|${selectedConflicts
      .map((conflict) => `${conflict.category}:${conflict.schemaId}`)
      .join(",")}`,
  });

  const hasAnySelection =
    selection.selectedNodeTypeIds.size > 0 ||
    selection.selectedRelationTypeIds.size > 0 ||
    selection.selectedRelationIds.size > 0 ||
    selection.selectedTemplateNames.size > 0;

  const handleApplyImport = async (): Promise<void> => {
    setIsApplyingImport(true);
    const warnings: string[] = [];
    try {
      const result = await applySchemaImportSelection({
        plugin,
        loadedSchemaFile,
        selection: selection.asSelectionPayload(),
        mergePlan: mergePlan.asMergePlan(),
        onWarning: (message) => warnings.push(message),
      });

      new Notice(buildImportCompleteMessage(result), 7000);
      if (warnings.length > 0) {
        new Notice(`Import warnings:\n${warnings.join("\n")}`, 6000);
      }
      onClose();
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      new Notice(`Failed to import schema: ${message}`, 6000);
      // Only the failure path stays mounted; the success path unmounted at onClose()
      setIsApplyingImport(false);
    }
  };

  const handleAdvanceFromSelection = (): void => {
    if (!hasAnySelection) {
      new Notice("Select at least one item to import.");
      return;
    }
    if (selectedConflicts.length > 0) {
      setStep("choose");
      return;
    }
    void handleApplyImport();
  };

  const isChoosingFields = step === "choose";
  const primaryLabel = isApplyingImport
    ? "Importing..."
    : isChoosingFields || selectedConflicts.length === 0
      ? "Import selected"
      : `Choose what to keep (${selectedConflicts.length})`;

  return (
    <div>
      <h3 className="mb-2">
        {isChoosingFields ? "Choose what to keep" : "Import schema preview"}
      </h3>
      <p className="text-muted mb-4 text-sm">
        Source file: {loadedSchemaFile.sourcePath}
      </p>

      {isChoosingFields ? (
        <SchemaConflictResolutionStep
          conflicts={selectedConflicts}
          mergePlan={mergePlan}
          sourceVaultName={schemaFile.vaultName}
        />
      ) : (
        <>
          <ImportSchemaPreviewSummary
            loadedSchemaFile={loadedSchemaFile}
            previewStats={previewStats}
          />
          <SchemaSelectionPanel
            source={source}
            selection={selection}
            nodeTypeNotes={buildExistingItemNotes({
              existingSchemaIds: loadedSchemaFile.matchPlan.existingNodeTypeIds,
              conflicts,
              category: "nodeType",
            })}
            relationTypeNotes={buildExistingItemNotes({
              existingSchemaIds:
                loadedSchemaFile.matchPlan.existingRelationTypeIds,
              conflicts,
              category: "relationType",
            })}
          />
        </>
      )}

      <div className="mt-6 flex justify-between">
        <button
          type="button"
          className="px-4 py-2"
          onClick={
            isChoosingFields
              ? () => {
                  mergePlan.reset();
                  setStep("select");
                }
              : onResetPreview
          }
          disabled={isApplyingImport}
        >
          {isChoosingFields ? "Back" : "Choose another file"}
        </button>
        <button
          type="button"
          className="!bg-accent !text-on-accent rounded px-4 py-2"
          onClick={
            isChoosingFields
              ? () => void handleApplyImport()
              : handleAdvanceFromSelection
          }
          disabled={isApplyingImport}
        >
          {primaryLabel}
        </button>
      </div>
    </div>
  );
};

const ImportSpecsContent = ({ plugin, onClose }: ImportSpecsModalProps) => {
  const [preview, setPreview] = useState<SpecImportPreview | null>(null);
  const [isSelectingFile, setIsSelectingFile] = useState(false);
  const [isApplyingImport, setIsApplyingImport] = useState(false);

  const handleSelectSchemaFile = async (): Promise<void> => {
    setIsSelectingFile(true);
    try {
      const nextPreview = await pickAndPreviewSchemaImport({ plugin });
      setPreview(nextPreview);
    } catch (error) {
      if (error instanceof NativeFileDialogCancelledError) return;
      if (error instanceof ZodError) {
        const fields = error.issues.map((i) => i.path.join(".")).join(", ");
        new Notice(
          `Schema file is incompatible with this version of the plugin. Invalid or missing fields: ${fields}`,
          8000,
        );
        return;
      }
      const message = error instanceof Error ? error.message : String(error);
      new Notice(`Failed to load schema file: ${message}`, 6000);
    } finally {
      setIsSelectingFile(false);
    }
  };

  if (!preview) {
    return (
      <div>
        <h3 className="mb-2">Import discourse graph schema</h3>
        <p className="text-muted mb-4 text-sm">
          Pick a <code>dg-schema-*.json</code> file from your computer to
          preview and choose exactly what to import.
        </p>

        <div className="mb-4 rounded border p-3 text-sm">
          Same dependency rules as export apply here during selection.
        </div>

        <div className="flex justify-between">
          <button type="button" className="px-4 py-2" onClick={onClose}>
            Cancel
          </button>
          <button
            type="button"
            className="!bg-accent !text-on-accent rounded px-4 py-2"
            onClick={() => void handleSelectSchemaFile()}
            disabled={isSelectingFile}
          >
            {isSelectingFile ? "Opening..." : "Choose schema file"}
          </button>
        </div>
      </div>
    );
  }

  return (
    <ImportPreviewSelection
      plugin={plugin}
      loadedSchemaFile={preview.loadedSchemaFile}
      previewStats={preview.previewStats}
      conflicts={preview.conflicts}
      isApplyingImport={isApplyingImport}
      setIsApplyingImport={setIsApplyingImport}
      onResetPreview={() => setPreview(null)}
      onClose={onClose}
    />
  );
};

export class ImportSpecsModal extends Modal {
  private plugin: DiscourseGraphPlugin;
  private root: Root | null = null;

  constructor(plugin: DiscourseGraphPlugin) {
    super(plugin.app);
    this.plugin = plugin;
  }

  onOpen(): void {
    this.contentEl.empty();
    this.root = createRoot(this.contentEl);
    this.root.render(
      <StrictMode>
        <ImportSpecsContent plugin={this.plugin} onClose={() => this.close()} />
      </StrictMode>,
    );
  }

  onClose(): void {
    if (this.root) {
      this.root.unmount();
      this.root = null;
    }
  }
}
import type {
  SchemaConflict,
  SchemaFieldChange,
} from "~/utils/schemaFieldDiff";
import { TEMPLATE_CONTENT_FIELD } from "~/utils/schemaFieldDiff";
import type { SchemaMergePlanState } from "~/components/useSchemaMergePlan";
import { getImportedTemplateFileName } from "~/utils/templates";
import { COLOR_PALETTE } from "~/utils/tldrawColors";

const FIELD_LABELS: Record<string, string> = {
  format: "Format",
  template: "Template",
  description: "Description",
  shortcut: "Shortcut",
  color: "Color",
  tag: "Tag",
  keyImage: "Key image",
  folderPath: "Folder path",
  complement: "Complement",
  content: "File contents",
};

const CATEGORY_HEADINGS: Record<SchemaConflict["category"], string> = {
  nodeType: "Node types",
  relationType: "Relation types",
  template: "Templates",
};

const CATEGORY_ORDER: SchemaConflict["category"][] = [
  "nodeType",
  "relationType",
  "template",
];

const formatFieldValue = (value: SchemaFieldChange["localValue"]): string => {
  if (value === undefined || value === "") return "empty";
  if (typeof value === "boolean") return value ? "on" : "off";
  // Collapse newlines so a multi-line value cannot stretch the row; the cell wraps rather than truncating.
  const collapsed = value.replace(/\s+/g, " ").trim();
  return collapsed.length === 0 ? "empty" : collapsed;
};

const isEmptyValue = (value: SchemaFieldChange["localValue"]): boolean => {
  return (
    value === undefined || (typeof value === "string" && value.trim() === "")
  );
};

/** Node types store a hex color, relation types a tldraw color name; both resolve to a swatch. */
const resolveSwatchColor = ({
  field,
  value,
}: {
  field: string;
  value: SchemaFieldChange["localValue"];
}): string | undefined => {
  if (field !== "color" || typeof value !== "string") return undefined;
  return COLOR_PALETTE[value] ?? (value.startsWith("#") ? value : undefined);
};

const describeTemplateBody = (
  value: SchemaFieldChange["localValue"],
): string => {
  if (typeof value !== "string") return formatFieldValue(value);
  const lineCount = value.split("\n").length;
  const byteCount = new TextEncoder().encode(value).length;
  return `${byteCount} bytes, ${lineCount} line${lineCount === 1 ? "" : "s"}`;
};

const ChoiceCell = ({
  conflict,
  change,
  isImportedSide,
  mergePlan,
}: {
  conflict: SchemaConflict;
  change: SchemaFieldChange;
  isImportedSide: boolean;
  mergePlan: SchemaMergePlanState;
}) => {
  const takesImported = mergePlan.isFieldSelected({
    category: conflict.category,
    schemaId: conflict.schemaId,
    field: change.field,
  });
  const isChosen = isImportedSide ? takesImported : !takesImported;
  const value = isImportedSide ? change.importedValue : change.localValue;
  const swatch = resolveSwatchColor({ field: change.field, value });

  const isTemplateBody =
    conflict.category === "template" && change.field === "content";
  const text = isTemplateBody
    ? describeTemplateBody(value)
    : formatFieldValue(value);

  return (
    <td
      className={`border-t p-0 align-top ${isChosen ? "bg-secondary" : ""}`}
      aria-selected={isChosen}
    >
      <label className="flex cursor-pointer items-start gap-2 px-2 py-2">
        <input
          className="mt-1 shrink-0"
          type="radio"
          name={`${conflict.category}:${conflict.schemaId}:${change.field}`}
          checked={isChosen}
          onChange={() =>
            mergePlan.toggleField({
              category: conflict.category,
              schemaId: conflict.schemaId,
              field: change.field,
              shouldSelect: isImportedSide,
            })
          }
        />
        {swatch && (
          <span
            className="mt-1 inline-block h-3 w-3 shrink-0 rounded border"
            style={{ backgroundColor: swatch }}
          />
        )}
        <span
          className={`min-w-0 break-words ${isChosen ? "font-medium" : "text-muted"} ${
            isEmptyValue(value) ? "italic" : ""
          }`}
          title={typeof value === "string" ? value : undefined}
        >
          {text}
        </span>
        {isImportedSide && isTemplateBody && (
          <span className="text-muted shrink-0" title="added as a new file">
            ⧉
          </span>
        )}
      </label>
    </td>
  );
};

const ItemChoiceTable = ({
  conflict,
  mergePlan,
  sourceVaultName,
}: {
  conflict: SchemaConflict;
  mergePlan: SchemaMergePlanState;
  sourceVaultName: string;
}) => {
  const selectedCount = mergePlan.countSelectedFields(conflict);
  const isAllLocal = selectedCount === 0;
  const isAllImported = selectedCount === conflict.changes.length;

  return (
    <section className="mb-3 rounded border p-3">
      <h5 className="mb-2 break-words text-base font-semibold">
        {conflict.label}
      </h5>
      <table className="w-full table-fixed border-collapse text-sm">
        <colgroup>
          <col className="w-1/4" />
          <col className="w-[37.5%]" />
          <col className="w-[37.5%]" />
        </colgroup>
        <thead>
          <tr>
            <th className="text-muted border-b px-2 pb-1 text-left align-bottom text-xs font-normal uppercase tracking-wide">
              Field
            </th>
            <th className="border-b p-0 text-left align-bottom font-normal">
              <button
                type="button"
                aria-pressed={isAllLocal}
                className={`w-full break-words rounded-none px-2 py-1 text-left text-xs font-semibold uppercase tracking-wide ${
                  isAllLocal
                    ? "!bg-accent !text-on-accent"
                    : "text-muted !bg-transparent"
                }`}
                onClick={() =>
                  mergePlan.setAllFields({ conflict, shouldSelect: false })
                }
              >
                Keep all mine
              </button>
            </th>
            <th className="border-b p-0 text-left align-bottom font-normal">
              <button
                type="button"
                aria-pressed={isAllImported}
                title={sourceVaultName}
                className={`w-full break-words rounded-none px-2 py-1 text-left text-xs font-semibold ${
                  isAllImported
                    ? "!bg-accent !text-on-accent"
                    : "text-muted !bg-transparent"
                }`}
                onClick={() =>
                  mergePlan.setAllFields({ conflict, shouldSelect: true })
                }
              >
                <span className="mr-1 uppercase tracking-wide">
                  Use all from
                </span>
                {sourceVaultName}
              </button>
            </th>
          </tr>
        </thead>
        <tbody>
          {conflict.changes.map((change) => (
            <tr key={change.field}>
              <td className="text-muted border-t px-2 py-2 align-top">
                {FIELD_LABELS[change.field] ?? change.field}
              </td>
              <ChoiceCell
                conflict={conflict}
                change={change}
                isImportedSide={false}
                mergePlan={mergePlan}
              />
              <ChoiceCell
                conflict={conflict}
                change={change}
                isImportedSide={true}
                mergePlan={mergePlan}
              />
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
};

export const SchemaConflictResolutionStep = ({
  conflicts,
  mergePlan,
  sourceVaultName,
}: {
  conflicts: SchemaConflict[];
  mergePlan: SchemaMergePlanState;
  sourceVaultName: string;
}) => {
  const totalFields = conflicts.reduce(
    (total, conflict) => total + conflict.changes.length,
    0,
  );
  const selectedFields = conflicts.reduce(
    (total, conflict) => total + mergePlan.countSelectedFields(conflict),
    0,
  );
  // A template left on the local value produces no copy, so only the chosen ones are named.
  const copiedTemplateConflicts = conflicts.filter(
    (conflict) =>
      conflict.category === "template" &&
      mergePlan.isFieldSelected({
        category: conflict.category,
        schemaId: conflict.schemaId,
        field: TEMPLATE_CONTENT_FIELD,
      }),
  );

  return (
    <>
      <div className="mb-4 rounded border p-3 text-sm">
        <div className="font-medium">
          {conflicts.length} item(s) already in this vault
        </div>
        <p className="text-muted mt-1">
          Every field starts on your value. Names are never changed by an
          import, because renaming a type does not retag the pages already using
          it.
        </p>
      </div>

      <div className="max-h-96 overflow-y-auto pr-1">
        {CATEGORY_ORDER.map((category) => {
          const categoryConflicts = conflicts.filter(
            (conflict) => conflict.category === category,
          );
          if (categoryConflicts.length === 0) return null;

          return (
            <section key={category} className="mb-5 last:mb-0">
              <h4 className="text-muted mb-2 border-b pb-1 text-xs font-semibold uppercase tracking-wide">
                {CATEGORY_HEADINGS[category]} ({categoryConflicts.length})
              </h4>
              {categoryConflicts.map((conflict) => (
                <ItemChoiceTable
                  key={`${conflict.category}:${conflict.schemaId}`}
                  conflict={conflict}
                  mergePlan={mergePlan}
                  sourceVaultName={sourceVaultName}
                />
              ))}
            </section>
          );
        })}
      </div>

      {copiedTemplateConflicts.length > 0 && (
        <p className="text-muted mt-2 text-xs">
          ⧉ Your template file is never overwritten — the imported version is
          added beside it as{" "}
          {copiedTemplateConflicts
            .map((conflict) =>
              getImportedTemplateFileName({
                templateName: conflict.schemaId,
                sourceName: sourceVaultName,
              }),
            )
            .map((name) => `${name}.md`)
            .join(", ")}
          , and node types using it are repointed at the copy.
        </p>
      )}

      <p className="mt-3 border-t pt-3 text-sm font-medium">
        {selectedFields} of {totalFields} field(s) will come from the file
      </p>
    </>
  );
};

            const errorMessage =
              error instanceof Error ? error.message : String(error);
            new Notice(`Refresh failed: ${errorMessage}`, 5000);
            console.error("Refresh failed:", error);
          });
      }
      return true;
    },
  });

  plugin.addCommand({
    id: "export-dg-schema",
    name: "Export discourse graph schema",
    callback: () => openExportSpecsModal(plugin),
  });

  plugin.addCommand({
    id: "import-dg-schema",
    name: "Import discourse graph schema",
    callback: () => {
      openImportSpecsModal(plugin);
    },
  });

  plugin.addCommand({
    id: "toggle-discourse-context",
    name: "Toggle discourse context",
    callback: () => {
      plugin.toggleDiscourseContextView();
    },
  });
              }
            }}
            placeholder="\"
            maxLength={1}
          />
        </div>
      </div>

      <div className="setting-item">
        <div className="setting-item-info">
          <div className="setting-item-name">Export discourse graph schema</div>
          <div className="setting-item-description">
            Export selected node types, relation types, relation triples, and
            templates to a JSON file named <code>{schemaFileName}</code>.
          </div>
        </div>
        <div className="setting-item-control">
          <button
            type="button"
            className="rounded border px-3 py-1.5 text-sm"
            onClick={() => openExportSpecsModal(plugin)}
          >
            Open export modal
          </button>
        </div>
      </div>
      <ToggleSetting
        name="Show discourse context overlay"
        description="Shows a badge next to links to discourse nodes with how many relations each one has. Select a badge to open its discourse context."
        checked={showDiscourseContextOverlay}
        onChange={handleDiscourseContextOverlayToggleChange}
import { Modal, Notice } from "obsidian";
import { StrictMode, useState } from "react";
import { createRoot, type Root } from "react-dom/client";
import type DiscourseGraphPlugin from "~/index";
import { exportSchemaSelection } from "~/utils/specExport";
import { NativeFileDialogCancelledError } from "~/utils/nativeJsonFileDialogs";
import { getDgSchemaFileName } from "~/utils/specValidation";
import { getTemplateFiles } from "~/utils/templates";
import {
  getReferencedTemplateNames,
  useSchemaSelection,
} from "~/components/useSchemaSelection";
import { SchemaSelectionModalBody } from "~/components/SchemaSelectionModalBody";

type ExportSpecsModalProps = {
  plugin: DiscourseGraphPlugin;
  onClose: () => void;
};

export const openExportSpecsModal = (plugin: DiscourseGraphPlugin): void => {
  new ExportSpecsModal(plugin).open();
};

const ExportSpecsContent = ({ plugin, onClose }: ExportSpecsModalProps) => {
  const [isExporting, setIsExporting] = useState(false);
  const outputFileName = getDgSchemaFileName(plugin.app.vault.getName());

  const source = {
    nodeTypes: plugin.settings.nodeTypes,
    relationTypes: plugin.settings.relationTypes,
    relationTriples: plugin.settings.discourseRelations,
    templateNames: getTemplateFiles(plugin.app),
  };

  const selection = useSchemaSelection({
    source,
    resetKey: "export",
    initialTemplateNames: [
      ...getReferencedTemplateNames(source.nodeTypes),
    ].filter((name) => source.templateNames.includes(name)),
  });

  const handleExport = async (): Promise<void> => {
    const payload = selection.asSelectionPayload();
    const hasSelection =
      payload.nodeTypeIds.length > 0 ||
      payload.relationTypeIds.length > 0 ||
      payload.discourseRelationIds.length > 0 ||
      payload.templateNames.length > 0;
    if (!hasSelection) {
      new Notice("Select at least one schema item or template to export.");
      return;
    }

    setIsExporting(true);
    const warnings: string[] = [];
    try {
      const filePath = await exportSchemaSelection({
        plugin,
        selection: payload,
        onWarning: (message) => warnings.push(message),
      });

      new Notice(`Exported schema to ${filePath}.`, 6000);
      if (warnings.length > 0) {
        new Notice(`Export warnings:\n${warnings.join("\n")}`, 6000);
      }

      onClose();
    } catch (error) {
      if (error instanceof NativeFileDialogCancelledError) {
        return;
      }
      const message = error instanceof Error ? error.message : String(error);
      new Notice(`Schema export failed: ${message}`, 6000);
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <SchemaSelectionModalBody
      title="Export discourse graph schema"
      description={`Select the node types, relation types, relation triples, and templates to include in ${outputFileName}.`}
      source={source}
      selection={selection}
      footerSecondaryLabel="Cancel"
      onFooterSecondaryClick={onClose}
      footerPrimaryLabel={isExporting ? "Exporting..." : "Export schema"}
      onFooterPrimaryClick={() => void handleExport()}
      isFooterPrimaryDisabled={isExporting}
    />
  );
};

export class ExportSpecsModal extends Modal {
  private plugin: DiscourseGraphPlugin;
  private root: Root | null = null;

  constructor(plugin: DiscourseGraphPlugin) {
    super(plugin.app);
    this.plugin = plugin;
  }

  onOpen(): void {
    this.contentEl.empty();
    this.root = createRoot(this.contentEl);
    this.root.render(
      <StrictMode>
        <ExportSpecsContent plugin={this.plugin} onClose={() => this.close()} />
      </StrictMode>,
    );
  }

  onClose(): void {
    if (this.root) {
      this.root.unmount();
      this.root = null;
    }
  }
}
