const updateSet = (
  previousSet: Set<string>,
  id: string,
  shouldSelect: boolean,
): Set<string> => {
  const nextSet = new Set(previousSet);
  if (shouldSelect) {
    nextSet.add(id);
  } else {
    nextSet.delete(id);
  }
  return nextSet;
};

